#include <stdio.h>
#include <string.h>

#define MOD 1000000007

long long dp[2][2][10005]; // dp[parity][position][oddness]

int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    if (k > n * n) {
        printf("0\n");
        return 0;
    }

    memset(dp, 0, sizeof(dp));
    dp[1][0][0] = 1; // empty permutation

    for (int i = 1; i <= n; i++) {
        int cur = i % 2;
        int prev = 1 - cur;
        memset(dp[cur], 0, sizeof(dp[cur]));

        for (int pos = 0; pos < i; pos++) {
            int add = 2 * pos; // adding i at position pos changes oddness by this amount
            for (int odd = 0; odd + add <= k; odd++) {
                if (dp[prev][pos][odd]) {
                    long long ways = dp[prev][pos][odd];
                    // Insert i at position pos
                    dp[cur][pos][odd + add] = (dp[cur][pos][odd + add] + ways) % MOD;
                    // Insert i at position pos+1 (new last position)
                    if (pos + 1 < i) {
                        dp[cur][pos + 1][odd + add] = (dp[cur][pos + 1][odd + add] + ways) % MOD;
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int pos = 0; pos <= n; pos++) {
        ans = (ans + dp[n % 2][pos][k]) % MOD;
    }
    printf("%lld\n", ans);
    return 0;
}

