/*
We count permutations p of {1..n} with
  oddness = sum_i |i - p[i]| = k.

Observation:
For any permutation, this sum is always even.
Let m = k / 2. Then
  sum_i |i - p[i]| = 2 * sum_{i: p[i] > i} (p[i] - i).
So we need the number of permutations whose total "rightward displacement"
is exactly m.

This is a classical Mahonian quantity: the multiset of values
sum_i max(p[i]-i,0) over permutations has the same distribution as inversion count.
Hence the answer equals the number of permutations of n with exactly m inversions.

Therefore:
- if k is odd, answer = 0
- else answer = number of permutations of n with inversion count k/2

DP:
dp[i][j] = number of permutations of size i with j inversions
dp[0][0] = 1
dp[i][j] = sum_{t=0..min(j,i-1)} dp[i-1][j-t]

Use prefix sums / sliding window:
dp_i[j] = dp_i[j-1] + dp_{i-1}[j] - (j>=i ? dp_{i-1}[j-i] : 0)

No modulus is specified, so we use arbitrary-precision nonnegative integers.
Implement a simple BigInteger in base 1e9.
*/

#define BASE 1000000000U

typedef struct {
    int len;
    unsigned int *d; /* little-endian base BASE */
} BigInt;

static void bigint_init_zero(BigInt *a) {
    a->len = 1;
    a->d = (unsigned int*)malloc(sizeof(unsigned int));
    a->d[0] = 0;
}

static void bigint_free(BigInt *a) {
    free(a->d);
    a->d = NULL;
    a->len = 0;
}

static void bigint_set_zero(BigInt *a) {
    free(a->d);
    a->len = 1;
    a->d = (unsigned int*)malloc(sizeof(unsigned int));
    a->d[0] = 0;
}

static void bigint_trim(BigInt *a) {
    while (a->len > 1 && a->d[a->len - 1] == 0) a->len--;
    a->d = (unsigned int*)realloc(a->d, sizeof(unsigned int) * a->len);
}

static void bigint_copy(BigInt *dst, const BigInt *src) {
    dst->len = src->len;
    dst->d = (unsigned int*)malloc(sizeof(unsigned int) * src->len);
    memcpy(dst->d, src->d, sizeof(unsigned int) * src->len);
}

static int bigint_is_zero(const BigInt *a) {
    return a->len == 1 && a->d[0] == 0;
}

static void bigint_add_inplace(BigInt *a, const BigInt *b) {
    int n = (a->len > b->len ? a->len : b->len);
    unsigned int *nd = (unsigned int*)calloc(n + 1, sizeof(unsigned int));
    unsigned long long carry = 0;
    for (int i = 0; i < n; i++) {
        unsigned long long sum = carry;
        if (i < a->len) sum += a->d[i];
        if (i < b->len) sum += b->d[i];
        nd[i] = (unsigned int)(sum % BASE);
        carry = sum / BASE;
    }
    int newlen = n;
    if (carry) nd[newlen++] = (unsigned int)carry;
    free(a->d);
    a->d = nd;
    a->len = newlen;
}

static void bigint_sub_inplace(BigInt *a, const BigInt *b) {
    /* assume a >= b */
    long long carry = 0;
    for (int i = 0; i < a->len; i++) {
        long long cur = (long long)a->d[i] - (i < b->len ? b->d[i] : 0) + carry;
        if (cur < 0) {
            cur += BASE;
            carry = -1;
        } else {
            carry = 0;
        }
        a->d[i] = (unsigned int)cur;
    }
    bigint_trim(a);
}

static void bigint_print(const BigInt *a) {
    printf("%u", a->d[a->len - 1]);
    for (int i = a->len - 2; i >= 0; i--) {
        printf("%09u", a->d[i]);
    }
    putchar('\n');
}

int main(void) {
    int n;
    long long k;
    if (scanf("%d %lld", &n, &k) != 2) return 0;

    if (k < 0 || (k & 1LL)) {
        printf("0\n");
        return 0;
    }

    long long mll = k / 2;
    long long maxInv = 1LL * n * (n - 1) / 2;
    if (mll > maxInv) {
        printf("0\n");
        return 0;
    }

    int m = (int)mll;

    BigInt *prev = (BigInt*)malloc((m + 1) * sizeof(BigInt));
    BigInt *cur  = (BigInt*)malloc((m + 1) * sizeof(BigInt));
    BigInt window;

    for (int j = 0; j <= m; j++) bigint_init_zero(&prev[j]);
    free(prev[0].d);
    prev[0].len = 1;
    prev[0].d = (unsigned int*)malloc(sizeof(unsigned int));
    prev[0].d[0] = 1;

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= m; j++) bigint_init_zero(&cur[j]);

        bigint_init_zero(&window);
        for (int j = 0; j <= m; j++) {
            bigint_add_inplace(&window, &prev[j]);
            if (j - i >= 0) bigint_sub_inplace(&window, &prev[j - i]);

            bigint_free(&cur[j]);
            bigint_copy(&cur[j], &window);
        }
        bigint_free(&window);

        for (int j = 0; j <= m; j++) bigint_free(&prev[j]);
        BigInt *tmp = prev; prev = cur; cur = tmp;
    }

    bigint_print(&prev[m]);

    for (int j = 0; j <= m; j++) bigint_free(&prev[j]);
    for (int j = 0; j <= m; j++) bigint_free(&cur[j]);
    free(prev);
    free(cur);

    return 0;
}

