        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();

        int maxOdd = n * n / 2 + 1;
        // dp[mask][oddness] = count
        long[][] dp = new long[1 << n][maxOdd + 1];
        dp[0][0] = 1;

        for (int mask = 0; mask < (1 << n); mask++) {
            int pos = Integer.bitCount(mask) + 1; // 1-indexed position to fill
            for (int odd = 0; odd <= maxOdd; odd++) {
                if (dp[mask][odd] == 0) continue;
                for (int v = 0; v < n; v++) {
                    if ((mask & (1 << v)) != 0) continue;
                    int val = v + 1;
                    int newOdd = odd + Math.abs(pos - val);
                    if (newOdd <= maxOdd) {
                        dp[mask | (1 << v)][newOdd] += dp[mask][odd];
                    }
                }
            }
        }

        int fullMask = (1 << n) - 1;
        System.out.println(k < maxOdd + 1 ? dp[fullMask][k] : 0);
    }
}

